/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(PriceDiscAdmSearch, AVASelectItems), FormControlEventType::Clicked)]
public void AVASelectItems_OnClicked(FormControl sender, FormControlEventArgs e)
{
    //FormStringControl   itemRelationTxtBox;

    AVATmpPriceDiscAdmSearchInventSel   inventSelTable;

    SysQueryRun queryRun = new SysQueryRun(queryStr(AVAInventTable));

    queryRun.form(formstr(SysQueryForm));

    queryRun.title("@NDX:NXAInventSelection");

    queryRun.prompt();

    selectionStr = SysOperationHelper::base64Encode(queryRun.pack()); 
    if (selectionStr)
    {
        ttsbegin;
        delete_from inventSelTable where inventSelTable.userId == curUserId();

        inventSelTable.clear();
        inventSelTable.UserId = curUserId();
        inventSelTable.SelectionStr = selectionStr;
        inventSelTable.insert();
        ttscommit;
        TmpPriceDiscAdmSearchInvent_ItemRelation.enabled(false);
        TmpPriceDiscAdmSearchInvent.itemrelation = "@NDX:NXAFilter";
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(PriceDiscAdmSearch, TmpPriceDiscAdmSearchInvent_ItemCode), FormControlEventType::SelectionChanged)]
public void TmpPriceDiscAdmSearchInvent_ItemCode_OnSelectionChanged(FormControl sender, FormControlEventArgs e)
{
    if (TmpPriceDiscAdmSearchInvent.itemCode == PriceDiscProductCodeType::Table)
    {
        AVASelectItems.enabled(true);
    }
    else
    {
        avaSelectItems.enabled(false);
    }
}
